import { VirtualList, Card } from "march/ui"

// yıldızları saymak: 100 000 satır, ama DOM'da yalnız görünenler; her onuncu satır bir takımyıldız
const sky = Array.from({ length: 100000 }, (_, i) => ({ id: i, name: i % 10 === 0 ? `✨ Takımyıldız ${i / 10 + 1}` : `⭐ Yıldız ${i + 1}` }))

export function StarCount() {
  return <Card title="100 000 yıldız">
    <div style={{ height: "260px" }}>
      <VirtualList label="Yıldızlar" items={sky} key={(s: { id: number }) => s.id} estimate={32}
        render={(s: () => { name: string }) => <div sx={{ p: 1 }}>{() => s().name}</div>} />
    </div>
  </Card>
}

import { VirtualList, Card, Button, Spinner } from "march/ui"
import { heart } from "march/icons"

// bir sohbetin geçmişi: farklı uzunlukta mesajlar, sona yaklaşınca 50 mesaj daha yüklenir; beğeni yalnız o satırı günceller
type Msg = { id: number; from: string; text: string; likes: number }
const PEOPLE = ["Elif", "Can", "Deniz", "Mert"]
const TEXTS = ["Selam!", "Toplantı kaçta?", "Sunumu paylaştım, bakabilir misin? Özellikle üçüncü sayfadaki tabloyu merak ediyorum.", "👍", "Akşam koşuya var mısın?"]
const page = (from: number): Msg[] => Array.from({ length: 50 }, (_, i) => ({ id: from + i, from: PEOPLE[(from + i) % 4]!, text: TEXTS[(from + i) % TEXTS.length]!, likes: 0 }))

// tek bir mesaj satırı
const Bubble = (props: { msg: () => Msg; onLike: () => void }) => <div sx={{ flex: ["row", "between"], gap: 2, p: 2 }}>
  <span><b>{() => props.msg().from}</b>: {() => props.msg().text}</span>
  <Button size="sm" variant="ghost" icon={heart} on:click={props.onLike}>{() => String(props.msg().likes)}</Button>
</div>

export function ChatHistory() {
  let $msgs = page(0)
  let $loading = false
  const more = () => { if ($loading) return; $loading = true; setTimeout(() => { $msgs = [...$msgs, ...page($msgs.length)]; $loading = false }, 500) }
  const like = (id: number) => $msgs = $msgs.map((m) => (m.id === id ? { ...m, likes: m.likes + 1 } : m))
  return <Card title={() => `Sohbet · ${$msgs.length} mesaj`}>
    <div style={{ height: "320px" }}>
      <VirtualList label="Mesajlar" items={() => $msgs} key={(m: Msg) => m.id} estimate={56} gap={4}
        onEndReached={more} footer={() => ($loading ? <Spinner label="Yükleniyor" /> : null)}
        render={(m: () => Msg) => <Bubble msg={m} onLike={() => like(m().id)} />} />
    </div>
  </Card>
}

import { VirtualList, Button } from "march/ui"

// VirtualList'in bütün özellikleri bir arada: items, key, render, estimate, overscan, gap, scroll, onEndReached,
// endDistance, header, footer, label, role, id, api (scrollToIndex), class
const rows = Array.from({ length: 1000 }, (_, i) => ({ id: i, title: `Satır ${i + 1}`, tall: i % 5 === 0 }))

export function VirtualListLab() {
  let $ends = 0
  let $gap = 0
  let jump: ((i: number, align?: "nearest" | "start" | "center") => void) | undefined
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      <Button size="sm" on:click={() => jump?.(499, "center")}>500. satıra git</Button>
      <Button size="sm" on:click={() => $gap = $gap ? 0 : 8}>{() => `Ara: ${$gap}`}</Button>
    </div>
    <p sx={{ text: "sm", color: "muted" }}>{() => `Sona ulaşıldı: ${$ends} kez`}</p>
    <div style={{ height: "300px" }}>
      {() => <VirtualList label="Laboratuvar listesi" id="lab-vlist" class="lab-vlist" role="list" scroll="self"
        items={rows} key={(r: { id: number }) => r.id} estimate={40} overscan={200} gap={$gap}
        endDistance={400} onEndReached={() => $ends++}
        api={(a: { scrollToIndex: (i: number, align?: "nearest" | "start" | "center") => void }) => { jump = a.scrollToIndex }}
        header={<p sx={{ text: "bold", p: 1 }}>Başlık: 1 000 satır</p>}
        footer={<p sx={{ color: "muted", p: 1 }}>Liste sonu</p>}
        render={(r: () => { title: string; tall: boolean }, i: number) => <div sx={{ p: 1 }}>{() => `${r().title} (#${i})`}{() => (r().tall ? <p sx={{ color: "muted" }}>Uzun satır: yüksekliği çizilince ölçülür</p> : null)}</div>} />}
    </div>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { VirtualListLab } from "./VirtualListLab.tsx"

// VirtualListLab'in testleri: kaydedince Testler sekmesinde çalışır
test("liste adını, kimliğini ve rolünü alır", () => {
  const s = renderTest(() => <VirtualListLab />)
  const list = s.get("#lab-vlist")
  expect(list?.getAttribute("role")).toBe("list")
  expect(s.get(".lab-vlist")).not.toBe(null)
})

test("başlık ve son satırı çizer", () => {
  const s = renderTest(() => <VirtualListLab />)
  expect(s.sees("Başlık: 1 000 satır")).toBe(true)
  expect(s.sees("Liste sonu")).toBe(true)
})

test("1 000 satırın hepsi DOM'a girmez", async () => {
  const s = renderTest(() => <VirtualListLab />)
  await s.flush()
  expect(s.all("[role=listitem]").length < 1000).toBe(true)
})

test("ara düğmesi değeri değiştirir", async () => {
  const s = renderTest(() => <VirtualListLab />)
  await s.click("Ara: 0")
  expect(s.sees("Ara: 8")).toBe(true)
})
